using System;
using System.IO;
using TrashAstronauts.Audio;
using UnityEditor;
using UnityEngine;

namespace TrashAstronauts.EditorTools
{
    /// <summary>
    /// Synthesizes every sound effect as a small mono 16-bit WAV. Nothing is downloaded or licensed from a
    /// third party: all audio in the project is generated by this file and can be regenerated at will.
    ///
    /// The file has three layers:
    ///   BuildAudio  assigns one recipe to each AudioLibrary field,
    ///   Synth       the recipes (what a door, a clang or the creature is made of),
    ///   Dsp         the building blocks (filters, modal resonators, pulse/formant voice, reverb, loop tools).
    /// Every recipe seeds its own System.Random from the clip name, so output is deterministic and a clip
    /// only changes on disk when its recipe changes.
    /// </summary>
    public static partial class Builder
    {
        const int SampleRate = 44100;

        static void BuildAudio()
        {
            var lib = LoadOrCreate<AudioLibrary>(DataDir + "/AudioLibrary.asset", out _);

            // Interaction
            lib.grab = Wav("grab", Synth.Grab());
            lib.buttonClick = Wav("button_click", Synth.ButtonClick());
            lib.deposit = Wav("deposit", Synth.Deposit());
            lib.depositJackpot = Wav("deposit_jackpot", Synth.DepositJackpot());
            lib.teleport = Wav("teleport", Synth.Teleport());
            lib.toolHolster = Wav("tool_holster", Synth.ToolHolster());
            lib.squeak = Wav("squeak", Synth.Squeak());
            lib.trickShot = Wav("trick_shot", Synth.TrickShot());
            lib.thruster = Wav("thruster", Synth.Thruster());
            lib.breathing = Wav("breathing", Synth.Breathing());
            lib.heartbeat = Wav("heartbeat", Synth.Heartbeat());

            // Tools
            lib.flashlightClick = Wav("flashlight_click", Synth.FlashlightClick());
            lib.scannerPing = Wav("scanner_ping", Synth.ScannerPing());
            lib.scannerHit = Wav("scanner_hit", Synth.ScannerHit());
            lib.cutterLoop = Wav("cutter_loop", Synth.CutterLoop());
            lib.cutterSparks = Wav("cutter_sparks", Synth.CutterSparks());
            lib.cutterOverheat = Wav("cutter_overheat", Synth.CutterOverheat());
            lib.panelBreak = Wav("panel_break", Synth.PanelBreak());
            lib.tranqFire = Wav("tranq_fire", Synth.TranqFire());
            lib.tranqHit = Wav("tranq_hit", Synth.TranqHit());

            // World. Variant 0 of each impact keeps the original file name, so existing references survive.
            lib.impactLightVariants = new[]
            {
                Wav("impact_light", Synth.ImpactLight(0)),
                Wav("impact_light_2", Synth.ImpactLight(1)),
                Wav("impact_light_3", Synth.ImpactLight(2)),
            };
            lib.impactLight = lib.impactLightVariants[0];
            lib.impactHeavyVariants = new[]
            {
                Wav("impact_heavy", Synth.ImpactHeavy(0)),
                Wav("impact_heavy_2", Synth.ImpactHeavy(1)),
                Wav("impact_heavy_3", Synth.ImpactHeavy(2)),
            };
            lib.impactHeavy = lib.impactHeavyVariants[0];
            lib.doorMove = Wav("door_move", Synth.DoorMove());
            lib.airlockHiss = Wav("airlock_hiss", Synth.AirlockHiss());
            lib.shipAmbience = Wav("ship_ambience", Synth.ShipAmbience());
            lib.tugAmbience = Wav("tug_ambience", Synth.TugAmbience());
            lib.powerDown = Wav("power_down", Synth.PowerDown());
            lib.powerUp = Wav("power_up", Synth.PowerUp());

            // Oxygen
            lib.oxygenLow = Wav("oxygen_low", Synth.OxygenLow());
            lib.oxygenCritical = Wav("oxygen_critical", Synth.OxygenCritical());

            // The creature
            lib.droneHum = Wav("drone_hum", Synth.DroneHum());
            lib.droneAlert = Wav("drone_alert", Synth.DroneAlert());
            lib.droneChase = Wav("drone_chase", Synth.DroneChase());
            lib.droneLost = Wav("drone_lost", Synth.DroneLost());
            lib.droneCatch = Wav("drone_catch", Synth.DroneCatch());
            lib.droneScare = Wav("drone_scare", Synth.DroneScare());

            // Results
            lib.resultSuccess = Wav("result_success", Synth.ResultSuccess());
            lib.resultPartial = Wav("result_partial", Synth.ResultPartial());
            lib.resultFail = Wav("result_fail", Synth.ResultFail());

            EditorUtility.SetDirty(lib);
            AssetDatabase.SaveAssets();
        }

        // ================================================================== recipes

        /// <summary>One method per clip. Each returns a finished buffer at <see cref="SampleRate"/>.</summary>
        static class Synth
        {
            // Partial ratios of a struck steel plate: inharmonic, getting denser with frequency.
            static readonly float[] k_Plate = { 1f, 1.58f, 2.24f, 2.92f, 3.46f, 4.16f, 5.03f, 5.87f, 6.71f, 7.94f, 9.12f, 10.57f, 12.3f, 14.2f, 16.6f, 19.1f };

            // Creature vocal tract shapes (formant centre frequencies in Hz) and how sharp/loud each formant is.
            static readonly float[] k_ThroatClosed = { 300f, 820f, 2200f, 3100f };
            static readonly float[] k_ThroatOpen = { 540f, 1180f, 2500f, 3400f };
            static readonly float[] k_ThroatRasp = { 650f, 1450f, 2650f, 3600f };
            static readonly float[] k_ThroatShriek = { 950f, 1900f, 3050f, 4300f };
            static readonly float[] k_ThroatQ = { 4f, 6f, 8f, 9f };
            static readonly float[] k_ThroatGain = { 1f, 0.6f, 0.3f, 0.15f };

            // Harmonic recipes for the tonal (UI / helmet speaker) sounds.
            static readonly float[] k_Chime = { 1f, 0.32f, 0.14f, 0.06f };
            static readonly float[] k_Dull = { 1f, 0.5f, 0.3f, 0.18f, 0.1f };
            static readonly float[] k_Beep = { 1f, 0.28f, 0.1f };
            static readonly float[] k_Buzzer = { 1f, 0f, 0.33f, 0f, 0.2f, 0f, 0.12f };
            static readonly float[] k_Motor = { 1f, 0.5f, 0.33f, 0.25f, 0.2f, 0.15f, 0.1f, 0.08f, 0.06f, 0.05f };

            // ---------------------------------------------------------- shared pieces

            /// <summary>A struck piece of metal: a bank of decaying inharmonic modes excited by a noise burst.</summary>
            static float[] Metal(int n, System.Random rng, float f0, int modes, float ring, float bright, float hardHz, float strikeMs, float damping)
            {
                int m = Mathf.Clamp(modes, 1, k_Plate.Length);
                var freqs = new float[m];
                var amps = new float[m];
                var decays = new float[m];
                for (int k = 0; k < m; k++)
                {
                    float ratio = k_Plate[k] * (k == 0 ? 1f : 1f + 0.05f * Dsp.Bi(rng));
                    freqs[k] = f0 * ratio;
                    amps[k] = (0.55f + 0.45f * Dsp.Uni(rng)) / (1f + k * (1f - Mathf.Clamp01(bright)) * 0.5f);
                    decays[k] = ring / (1f + (ratio - 1f) * Mathf.Max(0f, damping));   // high modes die sooner
                }
                return Dsp.Normalize(Dsp.Modal(n, rng, freqs, amps, decays, strikeMs, hardHz), 1f);
            }

            /// <summary>Heavy machinery stop: low metal body, a sub thump and a dull transient.</summary>
            static float[] Clunk(System.Random rng, float f0, float ring, float seconds)
            {
                int n = Dsp.Len(seconds);
                var y = Metal(n, rng, f0, 10, ring, 0.4f, 2200f, 2.5f, 0.6f);
                Dsp.Add(y, Dsp.Thump(n, f0 * 0.8f, f0 * 0.45f, 30f, 18f), 0.8f);
                Dsp.Add(y, Dsp.Burst(n, rng, 4f, 200f, 3000f), 0.4f);
                return Dsp.Normalize(y, 1f);
            }

            /// <summary>Small mechanical click: a tiny modal tick, a noise transient and a short body "thock".</summary>
            static void Click(float[] dst, System.Random rng, float at, float gain, float tickHz, float thockHz)
            {
                Dsp.Add(dst, Metal(Dsp.Len(0.03f), rng, tickHz, 5, 0.022f, 0.6f, 9000f, 0.25f, 0.3f), gain * 0.8f, at);
                Dsp.Add(dst, Dsp.Burst(Dsp.Len(0.01f), rng, 0.6f, 1500f, 9000f), gain * 0.6f, at);
                Dsp.Add(dst, Dsp.Thump(Dsp.Len(0.03f), thockHz, thockHz * 0.6f, 80f, 110f), gain * 0.3f, at);
            }

            /// <summary>
            /// One soft tonal note: slightly detuned partials, raised-cosine attack, exponential decay with
            /// the upper harmonics fading first, and a short release so nothing ends on a click.
            /// </summary>
            static void Note(float[] dst, float at, float hz, float dur, float gain, float attack, float decayRate, float[] harm)
            {
                int start = Mathf.RoundToInt(at * Dsp.SR);
                int n = Dsp.Len(dur);
                double up = Math.Pow(2.0, 4.0 / 1200.0), down = Math.Pow(2.0, -3.0 / 1200.0);
                for (int i = 0; i < n; i++)
                {
                    int j = start + i;
                    if (j < 0) continue;
                    if (j >= dst.Length) break;
                    double t = i / (double)Dsp.SR;
                    float tf = (float)t;
                    float env = Dsp.Smooth01(tf / Mathf.Max(0.001f, attack)) * Mathf.Exp(-decayRate * tf) * Dsp.Smooth01((dur - tf) / 0.04f);
                    double v = 0.0;
                    for (int h = 0; h < harm.Length; h++)
                    {
                        double f = hz * (h + 1.0);
                        if (f > Dsp.SR * 0.4) break;
                        if (harm[h] == 0f) continue;
                        double w = 2.0 * Math.PI * f * t;
                        double partial = Math.Sin(w) + 0.35 * Math.Sin(w * up + 0.7 * h) + 0.25 * Math.Sin(w * down + 1.9 * h);
                        v += harm[h] * partial * Math.Exp(-h * decayRate * 0.6 * t);
                    }
                    dst[j] += (float)v * env * gain * 0.6f;
                }
            }

            /// <summary>
            /// The creature's voice: an irregular glottal pulse train plus breath noise, pushed through a
            /// vocal tract that morphs between two formant shapes. Jitter, shimmer and a subharmonic make
            /// it sound like wet tissue instead of an oscillator.
            /// </summary>
            static float[] Voice(int n, System.Random rng, Func<float, float> f0, Func<float, float> amp, Func<float, float> breath,
                Func<float, float> morph, float[] shapeA, float[] shapeB, float jitter, float shimmer, float subharmonic, float openQuotient, float chest = 0.5f)
            {
                var src = Dsp.PulseTrain(n, rng, f0, jitter, shimmer, openQuotient, subharmonic);
                for (int i = 0; i < n; i++)
                {
                    float t = i / (float)Dsp.SR;
                    src[i] = src[i] * amp(t) + Dsp.Bi(rng) * breath(t);
                }
                var y = Dsp.Formants(src, shapeA, shapeB, k_ThroatQ, k_ThroatGain, morph);
                Dsp.Add(y, Dsp.LowPass(Dsp.Copy(src), 220f), chest);   // chest weight under the formants
                return y;
            }

            /// <summary>A wet mandible/throat click.</summary>
            static float[] CreatureClick(System.Random rng)
            {
                var c = Metal(Dsp.Len(0.03f), rng, Dsp.Range(rng, 1400f, 2600f), 3, 0.02f, 0.5f, 7000f, 0.25f, 0.2f);
                return Dsp.LowPass(c, 5000f);
            }

            /// <summary>Distant hull creak: a slow stick-slip pulse train ringing a few narrow metal resonances.</summary>
            static float[] Creak(System.Random rng, float seconds)
            {
                int n = Dsp.Len(seconds);
                float d = seconds;
                var src = Dsp.PulseTrain(n, rng, t => 48f + 55f * Dsp.Hump(t / d, 1f) + 9f * Mathf.Sin(Dsp.TwoPi * 3.1f * t), 0.12f, 0.4f, 0.3f, 0.2f);
                var y = Dsp.Formants(src, new[] { 410f, 873f, 1310f, 1960f }, new[] { 432f, 905f, 1370f, 2050f },
                    new[] { 28f, 32f, 30f, 26f }, new[] { 1f, 0.7f, 0.4f, 0.2f }, t => t / d);
                Dsp.Shape(y, t => Dsp.Hump(t / d, 1.5f));
                Dsp.LowPass(y, 1800f);
                return Dsp.Normalize(y, 1f);
            }

            /// <summary>One-shot finishing: clean up, remove DC, fade the ends, set the peak.</summary>
            static float[] Finish(float[] x, float peak, float fadeIn = 0.0001f, float fadeOut = 0.012f)
            {
                Dsp.Sanitize(x);
                Dsp.HighPass(x, 20f);
                Dsp.Fade(x, fadeIn, fadeOut);
                return Dsp.Normalize(x, peak);   // after the fades, so the peak is exactly what was asked for
            }

            /// <summary>Finishing for loops that pass through silence at the loop point (breathing, heartbeat).</summary>
            static float[] FinishSilentLoop(float[] x, float peak)
            {
                Dsp.Sanitize(x);
                Dsp.HighPass(x, 20f);
                Dsp.Fade(x, 0.002f, 0.03f);
                return Dsp.Normalize(x, peak);
            }

            /// <summary>Loop finishing: no fades (they would break the loop), DC removed by subtracting the mean.</summary>
            static float[] FinishLoop(float[] x, float peak)
            {
                Dsp.Sanitize(x);
                Dsp.RemoveMean(x);
                return Dsp.Normalize(x, peak);
            }

            // ---------------------------------------------------------- impacts and handling

            public static float[] ImpactLight(int variant)
            {
                var rng = Dsp.Seeded("impact_light_" + variant);
                float[] pitches = { 760f, 610f, 940f };
                float f0 = pitches[Mathf.Abs(variant) % pitches.Length];
                int n = Dsp.Len(0.4f);
                var y = Metal(n, rng, f0, 10, 0.45f, 0.7f, 6500f, 0.5f, 0.3f);
                Dsp.Add(y, Dsp.Burst(n, rng, 1.2f, 1800f, 9000f), 0.45f);
                Dsp.Add(y, Dsp.Thump(n, 240f, 150f, 60f, 55f), 0.35f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.8f);
                Dsp.LowPass(y, 8000f);
                y = Dsp.Reverb(y, 0.3f, 0.9f, 0.7f, 4500f, 0.4f);
                return Finish(y, 0.75f);
            }

            public static float[] ImpactHeavy(int variant)
            {
                var rng = Dsp.Seeded("impact_heavy_" + variant);
                float[] pitches = { 150f, 122f, 176f };
                float f0 = pitches[Mathf.Abs(variant) % pitches.Length];
                int n = Dsp.Len(0.85f);
                var y = Metal(n, rng, f0, 14, 1.0f, 0.6f, 3200f, 2.5f, 0.55f);
                Dsp.Add(y, Dsp.Thump(n, 105f, 52f, 30f, 14f), 0.5f);
                Dsp.Add(y, Dsp.Burst(n, rng, 5f, 200f, 3200f), 0.5f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.6f);
                Dsp.LowPass(y, 6500f);
                y = Dsp.Reverb(y, 0.3f, 1.1f, 0.9f, 3500f, 0.55f);
                return Finish(y, 0.9f);
            }

            public static float[] PanelBreak()
            {
                var rng = Dsp.Seeded("panel_break");
                int n = Dsp.Len(1.0f);
                var y = new float[n];
                var sheet = Metal(n, rng, 205f, 16, 1.0f, 0.8f, 5200f, 1.2f, 0.3f);
                Dsp.Shape(sheet, t => 1f + 0.35f * Mathf.Sin(Dsp.TwoPi * 8.5f * t) * Mathf.Exp(-3.5f * t));   // sheet-metal wobble
                Dsp.Add(y, sheet, 0.8f);
                Dsp.Add(y, Dsp.Burst(n, rng, 2.5f, 1200f, 10000f), 0.9f);   // the snap as the last weld lets go
                Dsp.Add(y, Dsp.Thump(n, 120f, 60f, 25f, 12f), 0.35f);
                float[] at = { 0.075f, 0.17f, 0.3f, 0.47f };
                float[] gain = { 0.5f, 0.38f, 0.25f, 0.14f };
                for (int k = 0; k < at.Length; k++)   // the freed panel rattling against the frame
                {
                    var hit = Metal(Dsp.Len(0.4f), rng, 205f * Dsp.Range(rng, 1.1f, 1.9f), 9, 0.35f, 0.8f, 6000f, 0.6f, 0.4f);
                    Dsp.Add(y, hit, gain[k], at[k] + 0.01f * Dsp.Bi(rng));
                }
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.4f);
                Dsp.LowPass(y, 8500f);
                y = Dsp.Reverb(y, 0.3f, 1.1f, 0.9f, 4000f, 0.65f);
                return Finish(y, 0.9f);
            }

            public static float[] Grab()
            {
                var rng = Dsp.Seeded("grab");
                int n = Dsp.Len(0.14f);
                var y = Dsp.Thump(n, 320f, 150f, 45f, 38f);                      // gloved palm closing on metal
                Dsp.Add(y, Dsp.Burst(n, rng, 14f, 500f, 2400f), 0.4f);          // glove fabric
                Dsp.Add(y, Metal(n, rng, 540f, 5, 0.07f, 0.4f, 1800f, 1.5f, 0.6f), 0.3f);
                Dsp.LowPass(y, 5000f);
                y = Dsp.Reverb(y, 0.1f, 0.25f, 0.5f, 3500f, 0.1f);
                return Finish(y, 0.7f);
            }

            public static float[] ToolHolster()
            {
                var rng = Dsp.Seeded("tool_holster");
                int n = Dsp.Len(0.2f);
                var y = new float[n];
                var scrape = Dsp.BandPass(Dsp.Noise(n, rng), t => 1800f + 9000f * t, 1.5f);   // tool sliding into the clip
                Dsp.Shape(scrape, t => t < 0.06f ? (t / 0.06f) * (t / 0.06f) : Mathf.Exp(-(t - 0.06f) * 120f));
                Dsp.Add(y, Dsp.Normalize(scrape, 1f), 0.3f);
                Dsp.Add(y, Metal(Dsp.Len(0.12f), rng, 1250f, 7, 0.07f, 0.7f, 7000f, 0.4f, 0.4f), 0.7f, 0.06f);   // latch
                Dsp.Add(y, Dsp.Thump(Dsp.Len(0.1f), 260f, 150f, 50f, 45f), 0.35f, 0.06f);
                Dsp.Add(y, Dsp.Burst(Dsp.Len(0.03f), rng, 1f, 1500f, 9000f), 0.4f, 0.06f);
                y = Dsp.Reverb(y, 0.12f, 0.25f, 0.5f, 4000f, 0.12f);
                return Finish(y, 0.7f);
            }

            public static float[] ButtonClick()
            {
                var rng = Dsp.Seeded("button_click");
                var y = new float[Dsp.Len(0.085f)];
                Click(y, rng, 0f, 1f, 2100f, 330f);        // press
                Click(y, rng, 0.05f, 0.35f, 2600f, 420f);  // spring return
                y = Dsp.Reverb(y, 0.06f, 0.15f, 0.4f, 5000f, 0.04f);
                return Finish(y, 0.75f, 0.0001f, 0.006f);
            }

            public static float[] FlashlightClick()
            {
                var rng = Dsp.Seeded("flashlight_click");
                var y = new float[Dsp.Len(0.045f)];
                Click(y, rng, 0f, 1f, 3000f, 420f);
                return Finish(y, 0.6f, 0.0001f, 0.006f);
            }

            // ---------------------------------------------------------- collection locker and jingles

            static void LockerThunk(float[] dst, System.Random rng, float gain)
            {
                int n = Dsp.Len(0.3f);
                var thunk = Metal(n, rng, 165f, 10, 0.22f, 0.5f, 2400f, 2.5f, 0.7f);
                Dsp.Add(thunk, Dsp.Thump(n, 130f, 75f, 30f, 22f), 0.6f);
                Dsp.Add(dst, Dsp.Normalize(thunk, 1f), gain);
            }

            public static float[] Deposit()
            {
                var rng = Dsp.Seeded("deposit");
                var y = new float[Dsp.Len(0.6f)];
                LockerThunk(y, rng, 1f);
                Note(y, 0.05f, 660f, 0.3f, 0.5f, 0.008f, 9f, k_Chime);
                Note(y, 0.2f, 880f, 0.4f, 0.5f, 0.008f, 7f, k_Chime);
                y = Dsp.Reverb(y, 0.15f, 0.4f, 0.7f, 5000f, 0.25f);
                return Finish(y, 0.6f);
            }

            public static float[] DepositJackpot()
            {
                var rng = Dsp.Seeded("deposit_jackpot");
                var y = new float[Dsp.Len(1.0f)];
                LockerThunk(y, rng, 0.9f);
                float[] notes = { 523f, 659f, 784f, 1047f };
                for (int k = 0; k < notes.Length; k++)
                    Note(y, 0.04f + 0.14f * k, notes[k], k == notes.Length - 1 ? 0.5f : 0.4f, 0.7f, 0.006f, k == notes.Length - 1 ? 5f : 7f, k_Chime);
                Note(y, 0.46f, 2093f, 0.45f, 0.18f, 0.01f, 8f, k_Chime);   // sparkle on top of the last note
                y = Dsp.Reverb(y, 0.18f, 0.5f, 0.7f, 5500f, 0.3f);
                return Finish(y, 0.65f);
            }

            public static float[] TrickShot()
            {
                var y = new float[Dsp.Len(0.95f)];
                float[] notes = { 659f, 784f, 988f, 1319f, 1568f };
                for (int k = 0; k < notes.Length; k++)
                    Note(y, 0.09f * k, notes[k], k == notes.Length - 1 ? 0.58f : 0.4f, 0.7f, 0.005f, k == notes.Length - 1 ? 5f : 8f, k_Chime);
                Note(y, 0.36f, 3136f, 0.5f, 0.14f, 0.012f, 9f, k_Chime);
                y = Dsp.Reverb(y, 0.16f, 0.45f, 0.7f, 5500f, 0.25f);
                return Finish(y, 0.6f);
            }

            public static float[] ResultSuccess()
            {
                var y = new float[Dsp.Len(1.4f)];
                float[] notes = { 392f, 494f, 587f, 784f };
                for (int k = 0; k < notes.Length; k++)
                {
                    bool last = k == notes.Length - 1;
                    Note(y, 0.2f * k, notes[k], last ? 0.8f : 0.55f, 0.7f, 0.012f, last ? 2.8f : 4.5f, k_Chime);
                    Note(y, 0.2f * k, notes[k] * 0.5f, last ? 0.8f : 0.5f, 0.25f, 0.02f, 4f, k_Beep);   // warmth an octave below
                }
                y = Dsp.Reverb(y, 0.18f, 0.6f, 0.8f, 5000f, 0.35f);
                return Finish(y, 0.5f);
            }

            public static float[] ResultPartial()
            {
                var y = new float[Dsp.Len(0.95f)];
                Note(y, 0f, 440f, 0.5f, 0.7f, 0.012f, 4.5f, k_Chime);
                Note(y, 0.3f, 392f, 0.65f, 0.7f, 0.012f, 3.5f, k_Chime);
                Note(y, 0.3f, 196f, 0.6f, 0.2f, 0.02f, 4f, k_Beep);
                y = Dsp.Reverb(y, 0.18f, 0.55f, 0.8f, 5000f, 0.3f);
                return Finish(y, 0.5f);
            }

            public static float[] ResultFail()
            {
                var y = new float[Dsp.Len(1.4f)];
                float[] notes = { 392f, 349f, 311f, 233f };
                for (int k = 0; k < notes.Length; k++)
                {
                    bool last = k == notes.Length - 1;
                    Note(y, 0.25f * k, notes[k], last ? 0.65f : 0.45f, 0.7f, 0.015f, last ? 2.2f : 3.5f, k_Dull);
                    Note(y, 0.25f * k, notes[k] * 0.5f, last ? 0.65f : 0.45f, 0.4f, 0.02f, 3f, k_Dull);
                }
                Dsp.LowPass(y, 2200f);
                y = Dsp.Reverb(y, 0.2f, 0.6f, 0.85f, 3500f, 0.35f);
                return Finish(y, 0.45f);
            }

            // ---------------------------------------------------------- suit

            public static float[] Teleport()
            {
                var rng = Dsp.Seeded("teleport");
                const float d = 0.26f;
                int n = Dsp.Len(d);
                var whoosh = Dsp.BandPass(Dsp.Noise(n, rng), t => 500f + 4200f * (t / d) * (t / d), 1.4f);
                Dsp.Shape(whoosh, t => Dsp.Hump(t / d, 1.5f));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(whoosh, 1f), 0.6f);
                var tone = Dsp.Osc(n, t => 320f + 1700f * Mathf.Pow(Mathf.Clamp01(t / d), 1.5f), k_Beep);
                var tone2 = Dsp.Osc(n, t => 1.007f * (320f + 1700f * Mathf.Pow(Mathf.Clamp01(t / d), 1.5f)), k_Beep);
                Dsp.Add(tone, tone2, 0.6f);
                Dsp.Shape(tone, t => Dsp.Hump(t / d, 2f));
                Dsp.Add(y, tone, 0.3f);
                y = Dsp.Reverb(y, 0.2f, 0.3f, 0.5f, 5000f, 0.15f);
                return Finish(y, 0.6f, 0.004f, 0.02f);
            }

            public static float[] Thruster()
            {
                var rng = Dsp.Seeded("thruster");
                int n = Dsp.Len(1.5f);
                // Cold gas through a small nozzle: mostly high hiss, a little body, a faint nozzle whistle.
                var jet = Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.HighPass(Dsp.BandPass(b, 2400f, 0.6f), 600f));
                var roar = Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.BandPass(b, 520f, 0.9f));
                var nozzle = Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.BandPass(b, 1150f, 6f));
                var turbulence = Dsp.Normalize(Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.LowPass(Dsp.LowPass(b, 18f), 18f)), 1f);
                var y = new float[n];
                Dsp.Add(y, Dsp.NormalizeRms(jet, 0.14f));
                Dsp.Add(y, Dsp.NormalizeRms(roar, 0.06f));
                Dsp.Add(y, Dsp.NormalizeRms(nozzle, 0.03f));
                for (int i = 0; i < n; i++) y[i] *= 1f + 0.18f * turbulence[i];
                return FinishLoop(y, 0.5f);
            }

            /// <summary>In ~1.2 s, a pause, out ~1.6 s, silence at the loop point. Deliberately subtle.</summary>
            public static float[] Breathing()
            {
                var rng = Dsp.Seeded("breathing");
                int n = Dsp.Len(3.4f);
                // Inhale is brighter (air rushing past the teeth), exhale is lower and rounder.
                var inhale = Dsp.BandPass(Dsp.Noise(n, rng), t => 1250f + 450f * Mathf.Clamp01(t / 1.2f), 1.1f);
                Dsp.Add(inhale, Dsp.BandPass(Dsp.Noise(n, rng), 2700f, 2f), 0.5f);
                Dsp.NormalizeRms(inhale, 0.1f);
                var exhale = Dsp.BandPass(Dsp.Noise(n, rng), t => 800f - 230f * Mathf.Clamp01((t - 1.55f) / 1.6f), 0.9f);
                Dsp.Add(exhale, Dsp.BandPass(Dsp.Noise(n, rng), 1500f, 1.8f), 0.4f);
                Dsp.NormalizeRms(exhale, 0.1f);
                var flutter = Dsp.RandomLfo(n, rng, 9f);
                var y = new float[n];
                for (int i = 0; i < n; i++)
                {
                    float t = i / (float)Dsp.SR;
                    float envIn = t < 1.2f ? Dsp.Hump(t / 1.2f, 1.5f) : 0f;
                    float u = (t - 1.55f) / 1.6f;
                    float envOut = u > 0f && u < 1f ? Dsp.Hump(Mathf.Pow(u, 0.75f), 1.2f) : 0f;   // exhale peaks early, trails off
                    y[i] = (inhale[i] * envIn * 0.8f + exhale[i] * envOut) * (1f + 0.15f * flutter[i]);
                }
                Dsp.Add(y, Dsp.BandPass(Dsp.Copy(y), 430f, 3f), 0.6f);   // boxy helmet resonance
                Dsp.LowPass(y, 4500f);
                return FinishSilentLoop(y, 0.5f);
            }

            /// <summary>Lub-dub. Each thump carries 2nd/3rd partials so it survives small headset speakers.</summary>
            public static float[] Heartbeat()
            {
                var rng = Dsp.Seeded("heartbeat");
                int n = Dsp.Len(0.85f);
                var y = new float[n];
                Beat(y, rng, 0f, 1f, 88f, 52f, 20f);       // lub
                Beat(y, rng, 0.26f, 0.75f, 108f, 64f, 27f);  // dub: a little higher and shorter
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.5f);
                Dsp.LowPass(y, 600f);
                return FinishSilentLoop(y, 0.5f);
            }

            static void Beat(float[] dst, System.Random rng, float at, float gain, float hzStart, float hzEnd, float decayRate)
            {
                int n = Dsp.Len(0.24f);
                Dsp.Add(dst, Dsp.Thump(n, hzStart, hzEnd, 35f, decayRate), gain, at);
                Dsp.Add(dst, Dsp.Thump(n, hzStart * 2f, hzEnd * 2f, 35f, decayRate * 1.25f), gain * 0.4f, at);
                Dsp.Add(dst, Dsp.Thump(n, hzStart * 3f, hzEnd * 3f, 35f, decayRate * 1.6f), gain * 0.3f, at);
                Dsp.Add(dst, Dsp.Burst(Dsp.Len(0.12f), rng, 10f, 40f, 300f), gain * 0.9f, at);
            }

            public static float[] OxygenLow()
            {
                // Two calm 700 Hz beeps from the helmet speaker.
                int n = Dsp.Len(0.6f);
                var y = Dsp.Osc(n, t => 700f * (1f + 0.003f * Mathf.Sin(Dsp.TwoPi * 5f * t)), k_Beep);
                Dsp.Shape(y, t => Dsp.Window(t, 0f, 0.18f, 0.008f) + Dsp.Window(t, 0.3f, 0.48f, 0.008f));
                Dsp.LowPass(y, 4000f);
                y = Dsp.Reverb(y, 0.08f, 0.2f, 0.4f, 5000f, 0.08f);
                return Finish(y, 0.4f, 0.001f, 0.02f);
            }

            public static float[] OxygenCritical()
            {
                // Three fast, buzzier 1 kHz beeps: same family as the low warning, clearly more urgent.
                int n = Dsp.Len(0.5f);
                var y = Dsp.Osc(n, t => 1000f, k_Buzzer);
                Dsp.Shape(y, t => Dsp.Window(t, 0f, 0.08f, 0.004f) + Dsp.Window(t, 0.16f, 0.24f, 0.004f) + Dsp.Window(t, 0.32f, 0.4f, 0.004f));
                Dsp.LowPass(y, 5000f);
                y = Dsp.Reverb(y, 0.08f, 0.2f, 0.4f, 5000f, 0.06f);
                return Finish(y, 0.28f, 0.001f, 0.02f);
            }

            // ---------------------------------------------------------- tools

            public static float[] ScannerPing()
            {
                int n = Dsp.Len(0.42f);
                Func<float, float> pitch = t => 1200f + 900f * (1f - Mathf.Exp(-18f * t));
                var y = Dsp.Osc(n, pitch, k_Beep);
                Dsp.Add(y, Dsp.Osc(n, t => 1.004f * pitch(t), k_Beep), 0.5f);
                Dsp.Shape(y, t => Dsp.Smooth01(t / 0.004f) * Mathf.Exp(-9f * t));
                var echo = Dsp.Copy(y);
                Dsp.Add(y, echo, 0.28f, 0.11f);   // sonar-style return
                Dsp.Add(y, echo, 0.1f, 0.22f);
                Dsp.LowPass(y, 7000f);
                y = Dsp.Reverb(y, 0.12f, 0.35f, 0.6f, 5000f, 0.12f);
                return Finish(y, 0.5f, 0.001f, 0.02f);
            }

            public static float[] ScannerHit()
            {
                var y = new float[Dsp.Len(0.28f)];
                Note(y, 0f, 1568f, 0.1f, 0.8f, 0.004f, 22f, k_Beep);
                Note(y, 0.1f, 2093f, 0.16f, 0.8f, 0.004f, 18f, k_Beep);
                y = Dsp.Reverb(y, 0.1f, 0.3f, 0.5f, 5500f, 0.08f);
                return Finish(y, 0.5f, 0.001f, 0.02f);
            }

            /// <summary>Plasma arc: mains-modulated hiss, a 120 Hz buzz with harmonics and random crackle.</summary>
            public static float[] CutterLoop()
            {
                var rng = Dsp.Seeded("cutter_loop");
                int n = Dsp.Len(2.0f);   // 60 Hz and all its harmonics complete whole cycles in 2 s
                var hiss = Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.HighPass(Dsp.BandPass(b, 3400f, 0.8f), 900f));
                Dsp.NormalizeRms(hiss, 0.2f);
                var buzz = new float[n];
                var phases = new float[14];
                for (int h = 0; h < phases.Length; h++) phases[h] = Dsp.Uni(rng) * Dsp.TwoPi;
                for (int i = 0; i < n; i++)
                {
                    double t = i / (double)Dsp.SR;
                    float rect = Mathf.Abs((float)Math.Sin(2.0 * Math.PI * 60.0 * t));   // rectified mains = 120 Hz envelope
                    hiss[i] *= 0.45f + 0.55f * rect * Mathf.Sqrt(rect);
                    double v = 0.3 * Math.Sin(2.0 * Math.PI * 60.0 * t);
                    for (int h = 0; h < phases.Length; h++)
                        v += Math.Sin(2.0 * Math.PI * 120.0 * (h + 1) * t + phases[h]) / Math.Pow(h + 1, 1.1);
                    buzz[i] = (float)v;
                }
                Dsp.NormalizeRms(buzz, 0.11f);
                var y = new float[n];
                Dsp.Add(y, hiss);
                Dsp.Add(y, buzz);
                for (int k = 0; k < 90; k++)   // crackle: sparse pops of very different sizes
                {
                    float size = Dsp.Uni(rng);
                    var pop = Dsp.Burst(Dsp.Len(0.012f), rng, Dsp.Range(rng, 0.15f, 1.4f), 2500f, 10000f);
                    Dsp.Add(y, pop, 0.08f + 0.5f * size * size * size, Dsp.Uni(rng) * 2.0f, true);
                }
                for (int i = 0; i < n; i++)   // slow flame flutter, whole cycles per loop
                    y[i] *= 1f + 0.08f * Dsp.LoopLfo(i, n, 3, 0.4f) + 0.05f * Dsp.LoopLfo(i, n, 11, 2.1f);
                y = Dsp.ReverbLoop(y, 0.1f, 0.3f, 0.5f, 5000f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.3f);
                return FinishLoop(y, 0.6f);
            }

            public static float[] CutterSparks()
            {
                var rng = Dsp.Seeded("cutter_sparks");
                int n = Dsp.Len(0.2f);
                var y = new float[n];
                for (int k = 0; k < 28; k++)
                {
                    float u = Dsp.Uni(rng);
                    float at = 0.17f * Mathf.Pow(u, 1.8f);   // densest right at the start
                    var spark = Dsp.Burst(Dsp.Len(0.02f), rng, Dsp.Range(rng, 0.3f, 2.2f), 1500f, 7500f);
                    Dsp.Add(y, spark, (0.3f + 0.7f * Dsp.Uni(rng)) * Mathf.Exp(-9f * at), at);
                }
                var sizzle = Dsp.BandPass(Dsp.Noise(n, rng), 5200f, 0.7f);
                var flutter = Dsp.RandomLfo(n, rng, 60f);
                for (int i = 0; i < n; i++) sizzle[i] *= Mathf.Exp(-28f * i / Dsp.SR) * (0.6f + 0.4f * flutter[i]);
                Dsp.Add(y, Dsp.Normalize(sizzle, 1f), 0.3f);
                Dsp.Add(y, Metal(Dsp.Len(0.06f), rng, 2900f, 4, 0.04f, 0.7f, 9000f, 0.3f, 0.3f), 0.15f, 0.004f);
                Dsp.LowPass(y, 9000f);
                y = Dsp.Reverb(y, 0.1f, 0.25f, 0.5f, 6000f, 0.1f);
                return Finish(y, 0.7f);
            }

            public static float[] CutterOverheat()
            {
                var rng = Dsp.Seeded("cutter_overheat");
                // Three descending beeps (0.14 s on, every 0.23 s), a rounded tone instead of a raw square wave.
                const float d = 0.66f;
                int n = Dsp.Len(d);
                float[] timbre = { 1f, 0f, 0.22f, 0f, 0.07f };
                var y = Dsp.Osc(n, t => 900f - 500f * t / 0.7f, timbre);
                Dsp.Add(y, Dsp.Osc(n, t => 1.006f * (900f - 500f * t / 0.7f), timbre), 0.25f);
                Dsp.Shape(y, t => Dsp.Window(t, 0f, 0.14f, 0.006f) + Dsp.Window(t, 0.23f, 0.37f, 0.006f) + Dsp.Window(t, 0.46f, 0.6f, 0.006f));
                Dsp.LowPass(y, 3200f);
                Dsp.Normalize(y, 1f);
                var vent = Dsp.BandPass(Dsp.Noise(n, rng), 4500f, 1f);   // heat venting under the alarm
                Dsp.Shape(vent, t => Dsp.Smooth01(t / 0.02f) * (0.25f + 0.75f * Mathf.Exp(-3f * t)) * Dsp.Smooth01((d - t) / 0.2f));
                Dsp.Add(y, Dsp.NormalizeRms(vent, 0.05f));
                y = Dsp.Reverb(y, 0.1f, 0.3f, 0.5f, 4000f, 0.1f);
                return Finish(y, 0.33f, 0.001f, 0.02f);
            }

            public static float[] TranqFire()
            {
                var rng = Dsp.Seeded("tranq_fire");
                int n = Dsp.Len(0.18f);
                var air = Dsp.BandPass(Dsp.Noise(n, rng), t => 900f + 3600f * Mathf.Exp(-45f * t), 1.3f);   // "thwip"
                Dsp.Shape(air, t => Dsp.Smooth01(t / 0.002f) * Mathf.Exp(-34f * t));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(air, 1f), 0.8f);
                Dsp.Add(y, Dsp.Thump(n, 300f, 110f, 60f, 42f), 0.35f);  // barrel pop
                Click(y, rng, 0f, 0.3f, 1900f, 380f);                  // trigger sear
                y = Dsp.Reverb(y, 0.1f, 0.25f, 0.5f, 5000f, 0.1f);
                return Finish(y, 0.7f);
            }

            public static float[] TranqHit()
            {
                var rng = Dsp.Seeded("tranq_hit");
                const float d = 0.45f;
                int n = Dsp.Len(d);
                var y = Dsp.Thump(n, 210f, 120f, 50f, 40f);
                Dsp.Gain(y, 0.8f);
                Dsp.Add(y, Dsp.Burst(n, rng, 2f, 600f, 5000f), 0.4f);
                Dsp.Add(y, Metal(n, rng, 430f, 5, 0.08f, 0.3f, 2000f, 1.5f, 0.6f), 0.3f);
                var inject = Dsp.Osc(n, t => 520f - 380f * t / d, k_Beep);   // sedative going in: falling tone
                Dsp.Shape(inject, t => Dsp.Smooth01(t / 0.02f) * Mathf.Exp(-5f * t));
                Dsp.Add(y, inject, 0.4f);
                var fizz = Dsp.BandPass(Dsp.Noise(n, rng), 5200f, 1.5f);
                Dsp.Shape(fizz, t => Dsp.Smooth01(t / 0.01f) * Mathf.Exp(-14f * t));
                Dsp.Add(y, Dsp.Normalize(fizz, 1f), 0.15f);
                y = Dsp.Reverb(y, 0.15f, 0.35f, 0.6f, 4500f, 0.2f);
                return Finish(y, 0.45f);
            }

            // ---------------------------------------------------------- world

            /// <summary>Start clunk, servo whine with gear-mesh harmonics for the 1.1 s door travel, end clunk.</summary>
            public static float[] DoorMove()
            {
                var rng = Dsp.Seeded("door_move");
                int n = Dsp.Len(1.3f);
                Func<float, float> speed = t => Dsp.Smooth01((t - 0.03f) / 0.15f) * (1f - Dsp.Smooth01((t - 0.95f) / 0.15f));
                Func<float, float> rpm = t => 30f + 165f * speed(t);
                var motor = Dsp.Osc(n, rpm, k_Motor);
                Dsp.Shape(motor, t => Mathf.Sqrt(speed(t)));
                var gear = Dsp.Osc(n, t => rpm(t) * 7.31f * (1f + 0.004f * Mathf.Sin(Dsp.TwoPi * 13f * t)), new[] { 1f, 0.35f, 0.12f });
                Dsp.Shape(gear, t => speed(t));
                var friction = Dsp.BandPass(Dsp.Noise(n, rng), 900f, 0.8f);
                Dsp.Shape(friction, t => speed(t) * (0.7f + 0.3f * Mathf.Sin(Dsp.TwoPi * 23f * t)));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(motor, 1f), 0.32f);
                Dsp.Add(y, Dsp.Normalize(gear, 1f), 0.12f);
                Dsp.Add(y, Dsp.NormalizeRms(friction, 0.05f));
                Dsp.Add(y, Clunk(rng, 115f, 0.3f, 0.45f), 0.8f, 0f);
                Dsp.Add(y, Clunk(rng, 92f, 0.35f, 0.2f), 1f, 1.08f);
                Dsp.LowPass(y, 6000f);
                y = Dsp.Reverb(y, 0.25f, 0.9f, 0.85f, 3500f, 0.45f);
                return Finish(y, 0.5f);
            }

            public static float[] AirlockHiss()
            {
                var rng = Dsp.Seeded("airlock_hiss");
                int n = Dsp.Len(1.6f);
                var air = Dsp.BandPass(Dsp.Noise(n, rng), t => 1700f + 4300f * Mathf.Exp(-2.2f * t), 1.1f);   // pressure dropping
                Dsp.Add(air, Dsp.HighPass(Dsp.Noise(n, rng), 2500f), 0.12f);
                var turbulence = Dsp.RandomLfo(n, rng, 25f);
                for (int i = 0; i < n; i++)
                {
                    float t = i / (float)Dsp.SR;
                    air[i] *= Dsp.Smooth01(t / 0.02f) * Mathf.Exp(-2.6f * t) * (1f + 0.12f * turbulence[i]);
                }
                var low = Dsp.LowPass(Dsp.LowPass(Dsp.Noise(n, rng), 260f), 260f);
                Dsp.Shape(low, t => Dsp.Smooth01(t / 0.03f) * Mathf.Exp(-5f * t));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(air, 1f), 0.8f);
                Dsp.Add(y, Dsp.Normalize(low, 1f), 0.2f);
                Dsp.Add(y, Dsp.Thump(Dsp.Len(0.3f), 85f, 48f, 20f, 16f), 0.25f);                     // valve thump
                Dsp.Add(y, Metal(Dsp.Len(0.25f), rng, 310f, 8, 0.15f, 0.4f, 3000f, 1.5f, 0.6f), 0.35f);
                y = Dsp.Reverb(y, 0.2f, 0.9f, 0.85f, 4500f, 0.4f);
                return Finish(y, 0.6f);
            }

            /// <summary>Derelict hull: deep rumble, faint power hum, slow swell, and a distant creak and ticks.</summary>
            public static float[] ShipAmbience()
            {
                var rng = Dsp.Seeded("ship_ambience");
                int n = Dsp.Len(4.0f);
                var rumble = Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.HighPass(Dsp.LowPass(Dsp.LowPass(b, 110f), 110f), 28f));
                Dsp.NormalizeRms(rumble, 0.16f);
                var mid = Dsp.NormalizeRms(Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.BandPass(b, 240f, 0.7f)), 0.045f);
                var air = Dsp.NormalizeRms(Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.LowPass(Dsp.BandPass(b, 1400f, 0.5f), 2500f)), 0.012f);
                var y = new float[n];
                for (int i = 0; i < n; i++)
                {
                    float swell = 1f + 0.22f * Dsp.LoopLfo(i, n, 1, 0f) + 0.12f * Dsp.LoopLfo(i, n, 3, 1.3f);
                    y[i] = rumble[i] * swell + mid[i] * (1f + 0.3f * Dsp.LoopLfo(i, n, 2, 0.5f)) + air[i];
                }
                Dsp.LoopTone(y, 55f, 0.07f, 0f);
                Dsp.LoopTone(y, 110f, 0.045f, 1.1f);
                Dsp.LoopTone(y, 165f, 0.02f, 2.3f);
                var beat = new float[n];
                Dsp.LoopTone(beat, 82.5f, 0.035f, 0.6f);
                for (int i = 0; i < n; i++) y[i] += beat[i] * (0.6f + 0.4f * Dsp.LoopLfo(i, n, 1, 2f));

                // Far-off structure noises, drenched in reverb that wraps around the loop point.
                var events = new float[n];
                Dsp.Add(events, Creak(rng, 0.8f), 0.06f, 1.15f, true);
                Dsp.Add(events, Dsp.LowPass(Metal(Dsp.Len(0.3f), rng, 700f, 6, 0.18f, 0.5f, 3000f, 1f, 0.5f), 2200f), 0.05f, 2.85f, true);
                Dsp.Add(events, Dsp.LowPass(Metal(Dsp.Len(0.3f), rng, 930f, 6, 0.14f, 0.5f, 3000f, 1f, 0.5f), 2200f), 0.03f, 3.22f, true);
                Dsp.Add(events, Clunk(rng, 70f, 0.4f, 0.5f), 0.05f, 0.35f, true);
                events = Dsp.ReverbLoop(events, 0.9f, 1.1f, 1f, 2500f);
                Dsp.Add(y, events);
                return FinishLoop(y, 0.5f);
            }

            /// <summary>The tug's cabin: soft air handling and a fan hum, much quieter than the wreck.</summary>
            public static float[] TugAmbience()
            {
                var rng = Dsp.Seeded("tug_ambience");
                int n = Dsp.Len(3.0f);
                var airflow = Dsp.NormalizeRms(Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.LowPass(Dsp.BandPass(b, 320f, 0.6f), 1800f)), 0.035f);
                var hiss = Dsp.NormalizeRms(Dsp.LoopFilter(Dsp.Noise(n, rng), b => Dsp.BandPass(b, 2600f, 0.7f)), 0.008f);
                var y = new float[n];
                for (int i = 0; i < n; i++)
                    y[i] = airflow[i] * (1f + 0.1f * Dsp.LoopLfo(i, n, 2, 0f) + 0.05f * Dsp.LoopLfo(i, n, 5, 2f)) + hiss[i];
                Dsp.LoopTone(y, 60f, 0.02f, 0f);
                Dsp.LoopTone(y, 120f, 0.03f, 0.9f);
                Dsp.LoopTone(y, 240f, 0.012f, 2.2f);
                Dsp.LoopTone(y, 360f, 0.006f, 4.1f);
                return FinishLoop(y, 0.2f);
            }

            public static float[] PowerDown()
            {
                var rng = Dsp.Seeded("power_down");
                const float d = 1.45f;
                int n = Dsp.Len(d);
                Func<float, float> k = t => { float r = Mathf.Clamp01(1f - t / d); return r * r; };
                Func<float, float> env = t => Dsp.Smooth01(t / 0.01f) * Mathf.Exp(-1.2f * t) * Dsp.Smooth01((d - t) / 0.05f);
                var hum = Dsp.Osc(n, t => 120f * k(t) + 18f, k_Motor);
                Dsp.ResLowPass(hum, t => 250f + 2800f * k(t), 1.2f);
                Dsp.Shape(hum, env);
                var sub = Dsp.Osc(n, t => 60f * Mathf.Clamp01(1f - t / d) + 22f, null);
                Dsp.Shape(sub, env);
                var wind = Dsp.BandPass(Dsp.Noise(n, rng), t => 200f + 1800f * k(t), 1.5f);
                Dsp.Shape(wind, t => Mathf.Exp(-2.2f * t));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(hum, 1f), 0.55f);
                Dsp.Add(y, sub, 0.2f);
                Dsp.Add(y, Dsp.Normalize(wind, 1f), 0.18f);
                Dsp.Add(y, Clunk(rng, 95f, 0.35f, 0.5f), 0.7f);   // main breaker dropping out
                y = Dsp.Reverb(y, 0.3f, 0.9f, 0.9f, 3000f, 0.6f);
                return Finish(y, 0.6f);
            }

            public static float[] PowerUp()
            {
                var rng = Dsp.Seeded("power_up");
                const float d = 0.95f;
                int n = Dsp.Len(d);
                Func<float, float> env = t => Dsp.Hump(t / d, 0.8f);
                var hum = Dsp.Osc(n, t => 30f + 110f * t / d, k_Motor);
                Dsp.ResLowPass(hum, t => 300f + 2400f * (t / d) * (t / d), 1.5f);
                Dsp.Shape(hum, env);
                var tone = Dsp.Osc(n, t => 60f + 180f * t / d, null);
                Dsp.Shape(tone, env);
                var wind = Dsp.BandPass(Dsp.Noise(n, rng), t => 300f + 2500f * (t / d) * (t / d), 1.5f);
                Dsp.Shape(wind, t => Dsp.Hump(t / d, 2f));
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(hum, 1f), 0.5f);
                Dsp.Add(y, tone, 0.3f);
                Dsp.Add(y, Dsp.Normalize(wind, 1f), 0.14f);
                Click(y, rng, 0f, 0.5f, 1500f, 180f);                     // relay closes
                Dsp.Add(y, Clunk(rng, 140f, 0.2f, 0.13f), 0.35f, 0.8f);   // contactors land
                y = Dsp.Reverb(y, 0.25f, 0.7f, 0.9f, 3500f, 0.45f);
                return Finish(y, 0.5f);
            }

            // ---------------------------------------------------------- the creature (kept quiet on purpose)

            /// <summary>Idle: two uneven, wet breaths of low growl per loop, with clusters of throat clicks.</summary>
            public static float[] DroneHum()
            {
                var rng = Dsp.Seeded("drone_hum");
                const float loop = 3.2f;
                int n = Dsp.Len(loop);
                int total = n + Dsp.Len(0.3f);
                float w = Dsp.TwoPi / loop;
                Func<float, float> breath = t =>
                    0.25f + 0.75f * Mathf.Pow(Mathf.Max(0f, 0.5f - 0.5f * Mathf.Cos(2f * w * t)), 1.4f) * (1f + 0.18f * Mathf.Sin(w * t + 0.8f));
                var y = Voice(total, rng,
                    t => 41f + 7f * Mathf.Sin(w * t + 0.3f) + 4f * Mathf.Sin(2f * w * t + 1.1f),
                    breath,
                    t => 0.05f + 0.1f * (1f - Mathf.Clamp01(breath(t))),   // air between the growls
                    t => 0.5f + 0.5f * Mathf.Sin(2f * w * t + 0.7f),
                    k_ThroatClosed, k_ThroatOpen, 0.14f, 0.35f, 0.45f, 0.3f, 0.15f);
                var gurgle = Dsp.RandomLfo(total, rng, 14f);
                for (int i = 0; i < total; i++) y[i] *= 1f - 0.3f * Mathf.Max(0f, gurgle[i]);
                Dsp.LowPass(y, 3800f);
                y = Dsp.LoopCrossfade(y, n);
                Dsp.Normalize(y, 1f);
                for (int c = 0; c < 5; c++)   // click clusters, each slowing down like a rattle running out
                {
                    float at = Dsp.Uni(rng) * loop;
                    int count = 2 + rng.Next(4);
                    float gap = Dsp.Range(rng, 0.045f, 0.07f);
                    for (int k = 0; k < count; k++)
                    {
                        Dsp.Add(y, CreatureClick(rng), Dsp.Range(rng, 0.1f, 0.22f), at, true);
                        at += gap;
                        gap *= 1.25f;
                    }
                }
                Dsp.SoftClip(y, 1.3f);
                return FinishLoop(y, 0.55f);
            }

            /// <summary>It noticed something: a growl that climbs into a shriek as the throat opens.</summary>
            public static float[] DroneAlert()
            {
                var rng = Dsp.Seeded("drone_alert");
                const float d = 0.8f;
                int n = Dsp.Len(d);
                Func<float, float> edge = t => Dsp.Smooth01(t / 0.03f) * Dsp.Smooth01((d - t) / 0.09f);
                var y = Voice(n, rng,
                    t => (170f + 820f * Mathf.Pow(Mathf.Clamp01(t / d), 2.2f)) * (1f + 0.05f * Mathf.Sin(Dsp.TwoPi * 31f * t)),
                    t => edge(t) * (0.5f + 0.5f * t / d),
                    t => edge(t) * (0.04f + 0.14f * t / d),
                    t => Mathf.Pow(Mathf.Clamp01(t / d), 1.3f),
                    k_ThroatOpen, k_ThroatShriek, 0.05f, 0.25f, 0.3f, 0.4f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.5f);
                Dsp.LowPass(y, 7000f);
                y = Dsp.Reverb(y, 0.3f, 0.9f, 0.85f, 4000f, 0.45f);
                return Finish(y, 0.5f, 0.002f, 0.02f);
            }

            /// <summary>Hunting: fast, panting rasp (14 pants per 1.6 s loop) with a dry rattle on top.</summary>
            public static float[] DroneChase()
            {
                var rng = Dsp.Seeded("drone_chase");
                const float loop = 1.6f;
                int n = Dsp.Len(loop);
                int total = n + Dsp.Len(0.2f);
                float w = Dsp.TwoPi / loop;
                Func<float, float> pant = t => 0.5f + 0.5f * Mathf.Sin(14f * w * t);
                var y = Voice(total, rng,
                    t => 74f + 14f * pant(t) + 5f * Mathf.Sin(w * t),
                    t => 0.35f + 0.65f * pant(t) * Mathf.Sqrt(pant(t)),
                    t => 0.12f + 0.2f * pant(t),
                    pant,
                    k_ThroatClosed, k_ThroatRasp, 0.2f, 0.4f, 0.55f, 0.35f);
                Dsp.LowPass(y, 5000f);
                y = Dsp.LoopCrossfade(y, n);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.8f);
                for (int k = 0; k < 24; k++)
                    Dsp.Add(y, CreatureClick(rng), Dsp.Range(rng, 0.08f, 0.2f), Dsp.Uni(rng) * loop, true);
                return FinishLoop(y, 0.5f);
            }

            /// <summary>Lost the trail: a groan that sags in pitch while the clicking peters out.</summary>
            public static float[] DroneLost()
            {
                var rng = Dsp.Seeded("drone_lost");
                const float d = 1.1f;
                int n = Dsp.Len(d);
                Func<float, float> env = t => Dsp.Smooth01(t / 0.05f) * Mathf.Exp(-1.6f * t) * Dsp.Smooth01((d - t) / 0.1f);
                var y = Voice(n, rng,
                    t => 190f - 135f * Mathf.Pow(Mathf.Clamp01(t / d), 0.7f) + 5f * Mathf.Sin(Dsp.TwoPi * 5.5f * t),
                    env,
                    t => env(t) * (0.06f + 0.1f * t / d),
                    t => 1f - t / d,
                    k_ThroatClosed, k_ThroatOpen, 0.1f, 0.3f, 0.4f, 0.45f);
                Dsp.Normalize(y, 1f);
                for (int k = 0; k < 11; k++)
                {
                    float at = 0.05f + 0.09f * k + 0.012f * Dsp.Bi(rng);
                    Dsp.Add(y, CreatureClick(rng), 0.25f * Mathf.Clamp01(1f - at / d), at);
                }
                Dsp.SoftClip(y, 1.3f);
                Dsp.LowPass(y, 5000f);
                y = Dsp.Reverb(y, 0.3f, 0.9f, 0.85f, 3500f, 0.5f);
                return Finish(y, 0.5f, 0.002f, 0.02f);
            }

            /// <summary>The grab: a short snarl with a bite at the front.</summary>
            public static float[] DroneCatch()
            {
                var rng = Dsp.Seeded("drone_catch");
                const float d = 0.9f;
                int n = Dsp.Len(d);
                Func<float, float> env = t => Dsp.Smooth01(t / 0.006f) * Mathf.Exp(-3f * t) * Dsp.Smooth01((d - t) / 0.08f);
                var y = Voice(n, rng,
                    t => 150f - 95f * t / d + 12f * Mathf.Sin(Dsp.TwoPi * 23f * t),
                    env,
                    t => env(t) * 0.35f,
                    t => Mathf.Exp(-4f * t),
                    k_ThroatClosed, k_ThroatRasp, 0.22f, 0.5f, 0.6f, 0.35f);
                Dsp.Normalize(y, 1f);
                Dsp.Add(y, Dsp.Burst(n, rng, 3f, 800f, 6000f), 0.6f);
                Dsp.Add(y, Dsp.Thump(n, 140f, 60f, 30f, 20f), 0.5f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 2.2f);
                Dsp.LowPass(y, 6000f);
                y = Dsp.Reverb(y, 0.28f, 0.9f, 0.85f, 3500f, 0.45f);
                return Finish(y, 0.6f, 0.001f, 0.02f);
            }

            /// <summary>
            /// Jumpscare sting: a rough screech over a sub-growl with a hard noise attack. Sharp, but the
            /// peak is held at about -8 dBFS because it plays right at the player's ears.
            /// </summary>
            public static float[] DroneScare()
            {
                var rng = Dsp.Seeded("drone_scare");
                const float d = 0.7f;
                int n = Dsp.Len(d);
                Func<float, float> env = t => Dsp.Smooth01(t / 0.003f) * Mathf.Exp(-3.2f * t) * Dsp.Smooth01((d - t) / 0.06f);
                var screech = Voice(n, rng,
                    t => (560f - 260f * t / d) * (1f + 0.12f * Mathf.Sin(Dsp.TwoPi * 47f * t)),
                    env,
                    t => env(t) * 0.3f,
                    t => 1f - t / d,
                    k_ThroatRasp, k_ThroatShriek, 0.08f, 0.4f, 0.5f, 0.4f);
                var growl = Voice(n, rng,
                    t => 95f - 25f * t / d,
                    env,
                    t => env(t) * 0.1f,
                    t => 0.5f,
                    k_ThroatClosed, k_ThroatOpen, 0.2f, 0.4f, 0.5f, 0.4f);
                var y = new float[n];
                Dsp.Add(y, Dsp.Normalize(screech, 1f), 0.8f);
                Dsp.Add(y, Dsp.Normalize(growl, 1f), 0.6f);
                Dsp.Add(y, Dsp.Burst(n, rng, 25f, 600f, 7000f), 0.5f);
                Dsp.Normalize(y, 1f);
                Dsp.SoftClip(y, 1.8f);
                Dsp.LowPass(y, 7000f);
                y = Dsp.Reverb(y, 0.2f, 0.5f, 0.8f, 4000f, 0.35f);
                return Finish(y, 0.398f, 0.0005f, 0.02f);   // -8 dBFS
            }

            // ---------------------------------------------------------- novelty

            /// <summary>Rubber duck: a reedy squeak that swoops up and back, then a small wheeze as it re-inflates.</summary>
            public static float[] Squeak()
            {
                var rng = Dsp.Seeded("squeak");
                const float d = 0.24f;
                int n = Dsp.Len(d);
                Func<float, float> pitch = t => (t < 0.09f ? 950f + 7000f * t : 1580f - 2600f * (t - 0.09f)) + 60f * Mathf.Sin(Dsp.TwoPi * 38f * t);
                float[] reedF = { 1450f, 2900f, 4600f };
                float[] reedQ = { 3f, 4f, 5f };
                float[] reedGain = { 1f, 0.6f, 0.3f };
                var squeeze = Dsp.Normalize(Dsp.Formants(Dsp.PulseTrain(n, rng, pitch, 0.01f, 0.05f, 0.55f, 0f), reedF, reedF, reedQ, reedGain, null), 1f);
                Dsp.Gain(squeeze, 0.55f);
                Dsp.Add(squeeze, Dsp.Osc(n, pitch, null), 0.5f);
                Dsp.Add(squeeze, Dsp.HighPass(Dsp.Noise(n, rng), 3000f), 0.03f);
                Dsp.Shape(squeeze, t => Dsp.Hump(t / d, 0.8f));

                const float d2 = 0.11f;
                int n2 = Dsp.Len(d2);
                Func<float, float> pitch2 = t => 1250f - 2200f * t;
                var release = Dsp.Normalize(Dsp.Formants(Dsp.PulseTrain(n2, rng, pitch2, 0.02f, 0.1f, 0.6f, 0f), reedF, reedF, reedQ, reedGain, null), 1f);
                Dsp.Gain(release, 0.5f);
                Dsp.Add(release, Dsp.Osc(n2, pitch2, null), 0.4f);
                Dsp.Add(release, Dsp.HighPass(Dsp.Noise(n2, rng), 2500f), 0.12f);
                Dsp.Shape(release, t => Dsp.Hump(t / d2, 1f));

                var y = new float[Dsp.Len(0.37f)];
                Dsp.Add(y, squeeze, 1f, 0f);
                Dsp.Add(y, release, 0.26f, 0.25f);
                y = Dsp.Reverb(y, 0.06f, 0.2f, 0.5f, 5000f, 0.06f);
                return Finish(y, 0.45f, 0.003f, 0.02f);
            }
        }

        // ================================================================== DSP building blocks

        /// <summary>
        /// Plain-C# signal processing on float buffers. Unless a summary says otherwise the filters work in
        /// place and return the same array so calls can be chained. Every recursive filter is guarded: a NaN
        /// or runaway value resets its state instead of poisoning the rest of the buffer.
        /// </summary>
        static class Dsp
        {
            public const int SR = SampleRate;
            public const float TwoPi = 2f * Mathf.PI;

            static readonly int[] k_CombDelays = { 1116, 1188, 1277, 1356, 1422, 1491 };
            static readonly int[] k_AllPassDelays = { 556, 441, 341 };

            // ---------------------------------------------------------- basics

            public static int Len(float seconds) => Mathf.Max(1, Mathf.RoundToInt(seconds * SR));

            /// <summary>Deterministic generator seeded from a name (FNV-1a, not string.GetHashCode which may vary).</summary>
            public static System.Random Seeded(string name)
            {
                unchecked
                {
                    uint h = 2166136261u;
                    for (int i = 0; i < name.Length; i++)
                    {
                        h ^= name[i];
                        h *= 16777619u;
                    }
                    return new System.Random((int)(h & 0x7fffffffu));
                }
            }

            public static float Uni(System.Random rng) => (float)rng.NextDouble();
            public static float Bi(System.Random rng) => (float)(rng.NextDouble() * 2.0 - 1.0);
            public static float Range(System.Random rng, float a, float b) => a + (b - a) * (float)rng.NextDouble();

            public static float Smooth01(float x)
            {
                x = Mathf.Clamp01(x);
                return x * x * (3f - 2f * x);
            }

            /// <summary>sin(pi*u)^power on 0..1, zero outside, never NaN.</summary>
            public static float Hump(float u, float power)
            {
                float s = Mathf.Max(0f, Mathf.Sin(Mathf.PI * Mathf.Clamp01(u)));
                return Mathf.Pow(s, power);
            }

            /// <summary>1 between start and end with smooth edges, 0 elsewhere.</summary>
            public static float Window(float t, float start, float end, float edge)
            {
                edge = Mathf.Max(0.0002f, edge);
                return Smooth01((t - start) / edge) * Smooth01((end - t) / edge);
            }

            public static float[] Copy(float[] x)
            {
                var y = new float[x.Length];
                Array.Copy(x, y, x.Length);
                return y;
            }

            public static float[] Gain(float[] x, float gain)
            {
                for (int i = 0; i < x.Length; i++) x[i] *= gain;
                return x;
            }

            /// <summary>Multiplies the buffer by env(timeInSeconds).</summary>
            public static float[] Shape(float[] x, Func<float, float> env)
            {
                for (int i = 0; i < x.Length; i++) x[i] *= env(i / (float)SR);
                return x;
            }

            /// <summary>Mixes src into dst starting at atSeconds. Out-of-range samples are dropped, or wrapped for loops.</summary>
            public static void Add(float[] dst, float[] src, float gain = 1f, float atSeconds = 0f, bool wrap = false)
            {
                if (dst == null || src == null || dst.Length == 0) return;
                int n = dst.Length;
                int at = Mathf.RoundToInt(atSeconds * SR);
                for (int i = 0; i < src.Length; i++)
                {
                    int j = at + i;
                    if (wrap)
                    {
                        j %= n;
                        if (j < 0) j += n;
                    }
                    else if (j < 0 || j >= n) continue;
                    dst[j] += src[i] * gain;
                }
            }

            // ---------------------------------------------------------- sources

            public static float[] Noise(int n, System.Random rng)
            {
                var y = new float[n];
                for (int i = 0; i < n; i++) y[i] = Bi(rng);
                return y;
            }

            /// <summary>Slow random wobble in -1..1 (low-passed noise), for turbulence and gurgle.</summary>
            public static float[] RandomLfo(int n, System.Random rng, float rateHz)
            {
                return Normalize(LowPass(LowPass(Noise(n, rng), rateHz), rateHz), 1f);
            }

            /// <summary>
            /// Phase-accumulating oscillator with a time-varying pitch. harmonics[h] is the level of partial
            /// h+1 (null = pure sine); partials above the safe band are skipped so sweeps never alias.
            /// </summary>
            public static float[] Osc(int n, Func<float, float> hz, float[] harmonics)
            {
                var y = new float[n];
                double phase = 0.0;
                for (int i = 0; i < n; i++)
                {
                    float f = Mathf.Clamp(hz(i / (float)SR), 0f, SR * 0.45f);
                    phase += f / SR;
                    phase -= Math.Floor(phase);
                    double w = 2.0 * Math.PI * phase;
                    if (harmonics == null)
                    {
                        y[i] = (float)Math.Sin(w);
                        continue;
                    }
                    double v = 0.0;
                    for (int h = 0; h < harmonics.Length; h++)
                    {
                        if (f * (h + 1) > SR * 0.42f) break;
                        if (harmonics[h] != 0f) v += harmonics[h] * Math.Sin(w * (h + 1));
                    }
                    y[i] = (float)v;
                }
                return y;
            }

            /// <summary>Decaying sine whose pitch drops from hzStart to hzEnd: the "body" of a thud.</summary>
            public static float[] Thump(int n, float hzStart, float hzEnd, float glideRate, float decayRate)
            {
                var y = new float[n];
                double phase = 0.0;
                for (int i = 0; i < n; i++)
                {
                    float t = i / (float)SR;
                    float f = hzEnd + (hzStart - hzEnd) * Mathf.Exp(-glideRate * t);
                    phase += f / SR;
                    y[i] = (float)Math.Sin(2.0 * Math.PI * phase) * Mathf.Exp(-decayRate * t);
                }
                return FadeTail(y);
            }

            /// <summary>Exponentially decaying noise transient, band-limited between hpHz and lpHz.</summary>
            public static float[] Burst(int n, System.Random rng, float decayMs, float hpHz, float lpHz)
            {
                var y = new float[n];
                float tau = Mathf.Max(0.00005f, decayMs * 0.001f) * SR;
                int m = Mathf.Min(n, Mathf.CeilToInt(tau * 9f) + 8);
                for (int i = 0; i < m; i++) y[i] = Bi(rng) * Mathf.Exp(-i / tau);
                HighPass(y, hpHz);
                LowPass(y, lpHz);
                return y;
            }

            /// <summary>
            /// Modal resonator bank: each mode is a two-pole resonator (frequency, level, time to -60 dB) and
            /// all of them are struck by the same short noise burst. A softer strike (lower hardnessHz,
            /// longer strikeMs) excites fewer high modes, exactly like a softer mallet. Returns a new buffer.
            /// </summary>
            public static float[] Modal(int n, System.Random rng, float[] freqs, float[] amps, float[] decays, float strikeMs, float hardnessHz)
            {
                var y = new float[n];
                float tau = Mathf.Max(0.00005f, strikeMs * 0.001f) * SR;
                int en = Mathf.Clamp(Mathf.CeilToInt(tau * 8f) + 4, 4, Mathf.Max(4, n));
                var strike = new float[en];
                for (int i = 0; i < en; i++) strike[i] = Bi(rng) * Mathf.Exp(-i / tau);
                LowPass(strike, hardnessHz);

                int modes = Mathf.Min(freqs.Length, Mathf.Min(amps.Length, decays.Length));
                for (int k = 0; k < modes; k++)
                {
                    float f = freqs[k];
                    if (!(f > 20f) || f > SR * 0.45f) continue;
                    double w = 2.0 * Math.PI * f / SR;
                    double r = Math.Exp(-6.908 / (Math.Max(0.004, decays[k]) * SR));   // -60 dB after decays[k] seconds
                    double c1 = 2.0 * r * Math.Cos(w), c2 = -r * r;
                    double g = amps[k] * Math.Sin(w);   // makes amps[k] the ringing amplitude for a unit impulse
                    double y1 = 0.0, y2 = 0.0;
                    for (int i = 0; i < n; i++)
                    {
                        double v = (i < en ? strike[i] : 0.0) + c1 * y1 + c2 * y2;
                        if (!(Math.Abs(v) < 1e9)) v = 0.0;
                        y2 = y1;
                        y1 = v;
                        y[i] += (float)(v * g);
                    }
                }
                return FadeTail(y);
            }

            /// <summary>
            /// Glottal-style pulse train for organic voices. Each cycle gets its own random period (jitter)
            /// and level (shimmer); subharmonic weakens every other pulse for a rough, growling octave-below.
            /// The flow pulse is differentiated (mouth radiation) and the result is peak-normalised to 1.
            /// </summary>
            public static float[] PulseTrain(int n, System.Random rng, Func<float, float> f0, float jitter, float shimmer, float openQuotient, float subharmonic)
            {
                var y = new float[n];
                float oq = Mathf.Clamp(openQuotient, 0.15f, 0.9f);
                float tp = oq * 0.67f, tn = oq - tp;
                float sub = Mathf.Clamp01(subharmonic);
                double phase = 0.0;
                float cycleRate = 1f, cycleAmp = 1f, previous = 0f;
                int cycle = 0;
                for (int i = 0; i < n; i++)
                {
                    float nominal = Mathf.Clamp(f0(i / (float)SR), 4f, 2500f);
                    phase += nominal * cycleRate / SR;
                    if (phase >= 1.0)
                    {
                        phase -= Math.Floor(phase);
                        cycle++;
                        cycleRate = Mathf.Max(0.3f, 1f + jitter * Bi(rng));
                        cycleAmp = Mathf.Max(0f, 1f + shimmer * Bi(rng)) * ((cycle & 1) == 1 ? 1f - sub : 1f);
                    }
                    float p = (float)phase, flow;
                    if (p < tp) flow = 0.5f * (1f - Mathf.Cos(Mathf.PI * p / tp));          // opening
                    else if (p < oq) flow = Mathf.Cos(0.5f * Mathf.PI * (p - tp) / tn);     // fast closure
                    else flow = 0f;                                                          // closed
                    flow *= cycleAmp;
                    y[i] = (flow - previous) * (100f / nominal);   // derivative, level-compensated for pitch
                    previous = flow;
                }
                return Normalize(y, 1f);
            }

            // ---------------------------------------------------------- filters

            static float OnePole(float hz) => 1f - Mathf.Exp(-TwoPi * Mathf.Clamp(hz, 1f, SR * 0.45f) / SR);

            /// <summary>One-pole low-pass (6 dB/octave).</summary>
            public static float[] LowPass(float[] x, float hz)
            {
                float a = OnePole(hz), y = 0f;
                for (int i = 0; i < x.Length; i++)
                {
                    y += a * (x[i] - y);
                    if (!(Mathf.Abs(y) < 1e6f)) y = 0f;
                    x[i] = y;
                }
                return x;
            }

            /// <summary>One-pole high-pass (6 dB/octave).</summary>
            public static float[] HighPass(float[] x, float hz)
            {
                float a = OnePole(hz), low = 0f;
                for (int i = 0; i < x.Length; i++)
                {
                    low += a * (x[i] - low);
                    if (!(Mathf.Abs(low) < 1e6f)) low = 0f;
                    x[i] -= low;
                }
                return x;
            }

            /// <summary>Resonant second-order section (RBJ cookbook), transposed direct form II.</summary>
            public struct Biquad
            {
                double b0, b1, b2, a1, a2, z1, z2;

                static void Prepare(float hz, float q, out double cos, out double alpha)
                {
                    double f = hz;
                    if (!(f > 10.0)) f = 10.0;
                    if (f > SR * 0.45) f = SR * 0.45;
                    double w = 2.0 * Math.PI * f / SR;
                    double qq = q;
                    if (!(qq > 0.1)) qq = 0.1;
                    cos = Math.Cos(w);
                    alpha = Math.Sin(w) / (2.0 * qq);
                }

                /// <summary>Band-pass with 0 dB gain at the centre frequency.</summary>
                public void SetBandPass(float hz, float q)
                {
                    Prepare(hz, q, out double cos, out double alpha);
                    double a0 = 1.0 + alpha;
                    b0 = alpha / a0;
                    b1 = 0.0;
                    b2 = -alpha / a0;
                    a1 = -2.0 * cos / a0;
                    a2 = (1.0 - alpha) / a0;
                }

                public void SetLowPass(float hz, float q)
                {
                    Prepare(hz, q, out double cos, out double alpha);
                    double a0 = 1.0 + alpha;
                    b0 = (1.0 - cos) * 0.5 / a0;
                    b1 = (1.0 - cos) / a0;
                    b2 = b0;
                    a1 = -2.0 * cos / a0;
                    a2 = (1.0 - alpha) / a0;
                }

                public float Process(float x)
                {
                    double y = b0 * x + z1;
                    z1 = b1 * x - a1 * y + z2;
                    z2 = b2 * x - a2 * y;
                    if (!(Math.Abs(y) < 1e6))
                    {
                        y = 0.0;
                        z1 = 0.0;
                        z2 = 0.0;
                    }
                    return (float)y;
                }
            }

            public static float[] BandPass(float[] x, float hz, float q)
            {
                var bq = new Biquad();
                bq.SetBandPass(hz, q);
                for (int i = 0; i < x.Length; i++) x[i] = bq.Process(x[i]);
                return x;
            }

            /// <summary>Band-pass whose centre follows hz(timeInSeconds).</summary>
            public static float[] BandPass(float[] x, Func<float, float> hz, float q)
            {
                var bq = new Biquad();
                for (int i = 0; i < x.Length; i++)
                {
                    if ((i & 31) == 0) bq.SetBandPass(hz(i / (float)SR), q);
                    x[i] = bq.Process(x[i]);
                }
                return x;
            }

            /// <summary>Resonant low-pass whose cutoff follows hz(timeInSeconds).</summary>
            public static float[] ResLowPass(float[] x, Func<float, float> hz, float q)
            {
                var bq = new Biquad();
                for (int i = 0; i < x.Length; i++)
                {
                    if ((i & 31) == 0) bq.SetLowPass(hz(i / (float)SR), q);
                    x[i] = bq.Process(x[i]);
                }
                return x;
            }

            /// <summary>
            /// Parallel formant filter: one band-pass per formant, each gliding from shapeA to shapeB as
            /// morph(t) goes 0..1 (null = stay on shapeA). Returns a new buffer.
            /// </summary>
            public static float[] Formants(float[] src, float[] shapeA, float[] shapeB, float[] q, float[] gain, Func<float, float> morph)
            {
                int n = src.Length;
                var y = new float[n];
                int count = Mathf.Min(Mathf.Min(shapeA.Length, shapeB.Length), Mathf.Min(q.Length, gain.Length));
                for (int k = 0; k < count; k++)
                {
                    var bq = new Biquad();
                    for (int i = 0; i < n; i++)
                    {
                        if ((i & 31) == 0)
                        {
                            float m = morph != null ? Mathf.Clamp01(morph(i / (float)SR)) : 0f;
                            bq.SetBandPass(shapeA[k] + (shapeB[k] - shapeA[k]) * m, q[k]);
                        }
                        y[i] += bq.Process(src[i]) * gain[k];
                    }
                }
                return y;
            }

            // ---------------------------------------------------------- level and edges

            /// <summary>Replaces NaN/infinite samples with silence.</summary>
            public static float[] Sanitize(float[] x)
            {
                for (int i = 0; i < x.Length; i++)
                    if (float.IsNaN(x[i]) || float.IsInfinity(x[i])) x[i] = 0f;
                return x;
            }

            public static float[] RemoveMean(float[] x)
            {
                if (x.Length == 0) return x;
                double sum = 0.0;
                for (int i = 0; i < x.Length; i++) sum += x[i];
                float mean = (float)(sum / x.Length);
                for (int i = 0; i < x.Length; i++) x[i] -= mean;
                return x;
            }

            /// <summary>Scales so the loudest sample sits at the given level. Silent buffers are left alone.</summary>
            public static float[] Normalize(float[] x, float peak)
            {
                Sanitize(x);
                float max = 0f;
                for (int i = 0; i < x.Length; i++) max = Mathf.Max(max, Mathf.Abs(x[i]));
                if (max < 1e-9f) return x;
                float g = peak / max;
                for (int i = 0; i < x.Length; i++) x[i] *= g;
                return x;
            }

            /// <summary>Scales to a target RMS: the predictable way to balance noise layers.</summary>
            public static float[] NormalizeRms(float[] x, float rms)
            {
                Sanitize(x);
                if (x.Length == 0) return x;
                double sum = 0.0;
                for (int i = 0; i < x.Length; i++) sum += (double)x[i] * x[i];
                float current = (float)Math.Sqrt(sum / x.Length);
                if (current < 1e-9f) return x;
                float g = rms / current;
                for (int i = 0; i < x.Length; i++) x[i] *= g;
                return x;
            }

            /// <summary>tanh soft clipper, rescaled so a full-scale input stays full-scale.</summary>
            public static float[] SoftClip(float[] x, float drive)
            {
                drive = Mathf.Max(0.01f, drive);
                float norm = 1f / (float)Math.Tanh(drive);
                for (int i = 0; i < x.Length; i++) x[i] = (float)Math.Tanh(x[i] * drive) * norm;
                return x;
            }

            /// <summary>Raised-cosine fade in and out so a clip never starts or stops on a click.</summary>
            public static float[] Fade(float[] x, float inSeconds, float outSeconds)
            {
                int n = x.Length;
                int fi = Mathf.Min(n / 2, Mathf.RoundToInt(inSeconds * SR));
                int fo = Mathf.Min(n / 2, Mathf.RoundToInt(outSeconds * SR));
                for (int i = 0; i < fi; i++) x[i] *= Smooth01(i / (float)fi);
                for (int i = 0; i < fo; i++) x[n - 1 - i] *= Smooth01(i / (float)fo);
                return x;
            }

            /// <summary>Fades the last tenth (at most 30 ms) of a generated ring so truncating it cannot click.</summary>
            static float[] FadeTail(float[] x)
            {
                int n = x.Length;
                int fo = Mathf.Min(n / 10, SR * 30 / 1000);
                for (int i = 0; i < fo; i++) x[n - 1 - i] *= i / (float)fo;
                return x;
            }

            // ---------------------------------------------------------- reverb

            /// <summary>
            /// Schroeder reverb, wet signal only: parallel damped feedback combs into series all-passes.
            /// size scales the delay lengths (small = tight metallic box), rt60 sets the comb feedback,
            /// dampHz darkens the tail. Output has length n; input beyond x is treated as silence.
            /// </summary>
            static float[] ReverbWet(float[] x, int n, float rt60, float size, float dampHz)
            {
                var acc = new float[n];
                size = Mathf.Clamp(size, 0.2f, 2f);
                rt60 = Mathf.Max(0.05f, rt60);
                int pre = Mathf.RoundToInt(0.006f * SR * size);
                float damp = OnePole(dampHz);

                for (int c = 0; c < k_CombDelays.Length; c++)
                {
                    int d = Mathf.Max(16, Mathf.RoundToInt(k_CombDelays[c] * size));
                    float g = Mathf.Min(0.97f, Mathf.Pow(10f, -3f * d / (rt60 * SR)));
                    var buf = new float[d];
                    int p = 0;
                    float lp = 0f;
                    for (int i = 0; i < n; i++)
                    {
                        int j = i - pre;
                        float input = j >= 0 && j < x.Length ? x[j] : 0f;
                        float output = buf[p];
                        lp += damp * (output - lp);
                        if (!(Mathf.Abs(lp) < 1e4f)) lp = 0f;
                        buf[p] = input + lp * g;
                        if (++p >= d) p = 0;
                        acc[i] += output;
                    }
                }
                for (int i = 0; i < n; i++) acc[i] *= 0.6f;

                for (int a = 0; a < k_AllPassDelays.Length; a++)
                {
                    int d = Mathf.Max(8, Mathf.RoundToInt(k_AllPassDelays[a] * size));
                    const float g = 0.5f;
                    var buf = new float[d];
                    int p = 0;
                    for (int i = 0; i < n; i++)
                    {
                        float delayed = buf[p];
                        float input = acc[i];
                        float output = delayed - g * input;
                        buf[p] = input + g * output;
                        if (++p >= d) p = 0;
                        acc[i] = output;
                    }
                }
                return Sanitize(acc);
            }

            /// <summary>
            /// One-shot reverb. Returns a NEW, longer buffer: the dry signal plus wet * reverb, extended by
            /// tailSeconds (default: most of rt60) and faded out at the very end.
            /// </summary>
            public static float[] Reverb(float[] x, float wet, float rt60, float size = 1f, float dampHz = 4500f, float tailSeconds = -1f)
            {
                if (wet <= 0f) return x;
                int tail = Mathf.RoundToInt((tailSeconds >= 0f ? tailSeconds : Mathf.Min(rt60 * 0.9f, 1.5f)) * SR);
                int n = x.Length + Mathf.Max(0, tail);
                var wetBuffer = ReverbWet(x, n, rt60, size, dampHz);
                var y = new float[n];
                for (int i = 0; i < n; i++) y[i] = (i < x.Length ? x[i] : 0f) + wet * wetBuffer[i];
                int fade = Mathf.Min(n / 2, Mathf.Max(SR / 100, tail / 2));
                for (int i = 0; i < fade; i++) y[n - 1 - i] *= Smooth01(i / (float)fade);
                return y;
            }

            /// <summary>
            /// Reverb for a loop: the buffer is fed through twice and the second pass is kept, so the tail of
            /// the loop's end is already ringing at its start. Same length as the input; returns a new buffer.
            /// </summary>
            public static float[] ReverbLoop(float[] x, float wet, float rt60, float size = 1f, float dampHz = 4500f)
            {
                int n = x.Length;
                var twice = new float[n * 2];
                Array.Copy(x, 0, twice, 0, n);
                Array.Copy(x, 0, twice, n, n);
                var wetBuffer = ReverbWet(twice, n * 2, rt60, size, dampHz);
                var y = new float[n];
                for (int i = 0; i < n; i++) y[i] = x[i] + wet * wetBuffer[n + i];
                return y;
            }

            // ---------------------------------------------------------- loop tools

            /// <summary>
            /// Runs a (time-invariant) filter chain over a periodic buffer so the result is periodic too:
            /// the chain processes two copies back to back and the second, settled copy is returned.
            /// </summary>
            public static float[] LoopFilter(float[] x, Func<float[], float[]> chain)
            {
                int n = x.Length;
                var twice = new float[n * 2];
                Array.Copy(x, 0, twice, 0, n);
                Array.Copy(x, 0, twice, n, n);
                var processed = chain(twice) ?? twice;
                var y = new float[n];
                Array.Copy(processed, Mathf.Min(n, Mathf.Max(0, processed.Length - n)), y, 0, Mathf.Min(n, processed.Length));
                return y;
            }

            /// <summary>
            /// Makes a loop out of a buffer that was rendered a little too long: the surplus after loopLength
            /// is equal-power crossfaded into the head, so the last sample flows straight into the first.
            /// </summary>
            public static float[] LoopCrossfade(float[] x, int loopLength)
            {
                loopLength = Mathf.Clamp(loopLength, 1, x.Length);
                var y = new float[loopLength];
                Array.Copy(x, y, loopLength);
                int fade = Mathf.Min(x.Length - loopLength, loopLength / 2);
                for (int i = 0; i < fade; i++)
                {
                    float k = i / (float)fade;
                    y[i] = x[i] * Mathf.Sin(k * Mathf.PI * 0.5f) + x[loopLength + i] * Mathf.Cos(k * Mathf.PI * 0.5f);
                }
                return y;
            }

            /// <summary>Sine LFO that completes a whole number of cycles in a loop of n samples.</summary>
            public static float LoopLfo(int i, int n, int cycles, float phase)
            {
                return (float)Math.Sin(2.0 * Math.PI * cycles * i / n + phase);
            }

            /// <summary>Adds a steady tone, with hz snapped to the nearest whole number of cycles per loop.</summary>
            public static void LoopTone(float[] dst, float hz, float gain, float phase)
            {
                int n = dst.Length;
                int cycles = Mathf.Max(1, Mathf.RoundToInt(hz * n / SR));
                for (int i = 0; i < n; i++) dst[i] += gain * (float)Math.Sin(2.0 * Math.PI * cycles * (i / (double)n) + phase);
            }
        }

        // ================================================================== WAV output

        /// <summary>
        /// Writes a finished buffer as Assets/.../Generated/Audio/{name}.wav (mono, 16-bit, 44.1 kHz) and
        /// returns the imported clip. The file is only rewritten and re-imported when its bytes actually
        /// change, so rebuilding with unchanged recipes leaves the assets (and their .meta GUIDs) untouched.
        /// Import settings are whatever the existing .meta says (Unity defaults for a new clip).
        /// </summary>
        static AudioClip Wav(string name, float[] data)
        {
            int count = data != null ? data.Length : 0;
            int dataBytes = count * 2;
            var bytes = new byte[44 + dataBytes];
            using (var stream = new MemoryStream(bytes))
            using (var writer = new BinaryWriter(stream))
            {
                writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));
                writer.Write(36 + dataBytes);
                writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVE"));
                writer.Write(System.Text.Encoding.ASCII.GetBytes("fmt "));
                writer.Write(16);
                writer.Write((short)1);            // PCM
                writer.Write((short)1);            // mono
                writer.Write(SampleRate);
                writer.Write(SampleRate * 2);      // bytes per second
                writer.Write((short)2);            // block align
                writer.Write((short)16);           // bits per sample
                writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));
                writer.Write(dataBytes);
                for (int i = 0; i < count; i++)
                {
                    float v = data[i];
                    if (float.IsNaN(v) || float.IsInfinity(v)) v = 0f;
                    writer.Write((short)Mathf.RoundToInt(Mathf.Clamp(v, -1f, 1f) * 32767f));
                }
            }

            string path = AudioDir + "/" + name + ".wav";
            bool unchanged = false;
            if (File.Exists(path))
            {
                var existing = File.ReadAllBytes(path);
                unchanged = existing.Length == bytes.Length;
                for (int i = 0; unchanged && i < bytes.Length; i++)
                    if (existing[i] != bytes[i]) unchanged = false;
            }
            if (!unchanged)
            {
                File.WriteAllBytes(path, bytes);
                AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            }

            var clip = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            if (clip == null)
            {
                AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
                clip = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
            }
            return clip;
        }

        /// <summary>
        /// Per-sample convenience overload: sample(timeSeconds, durationSeconds). Loops get their last
        /// 100 ms crossfaded into the head (and are that much shorter); one-shots get a short fade out.
        /// </summary>
        static AudioClip Wav(string name, float seconds, Func<float, float, float> sample, bool loop = false)
        {
            int count = Mathf.Max(1, Mathf.RoundToInt(seconds * SampleRate));
            var data = new float[count];
            for (int i = 0; i < count; i++) data[i] = sample(i / (float)SampleRate, seconds);

            if (loop)
            {
                int fade = Mathf.Min(count / 4, SampleRate / 10);
                data = Dsp.LoopCrossfade(data, count - fade);
            }
            else
            {
                Dsp.Fade(data, 0f, 0.003f);
            }
            return Wav(name, data);
        }
    }
}
